html:
{#- Lab Report for one Diagnostic Test. Anything not Reported prints with a
    PROVISIONAL band: only a verified report should leave the lab. -#}
{%- set signature_label = frappe.db.get_single_value("Lab Settings", "signature_label") -%}
{%- set report_footer = frappe.db.get_single_value("Lab Settings", "report_footer") -%}
{%- set visit = frappe.db.get_value("Patient Visit", doc.patient_visit, ["uhin_id", "name"], as_dict=1) if doc.patient_visit else None -%}
{%- set doctor = frappe.db.get_value("Doctor Consultation", doc.doctor_consultation, "doctor") -%}
{%- set dept = frappe.db.get_value("Lab Test Template", doc.lab_test_template, "department") if doc.lab_test_template else None -%}
{%- macro user_name(u) -%}{{ frappe.db.get_value("User", u, "full_name") or u }}{%- endmacro -%}
<style>
  .lr { font-size: 12.5px; color: #1f2933; }
  .lr h2 { font-size: 17px; margin: 0 0 2px; letter-spacing: .02em; }
  .lr .sub { color: #52606d; margin-bottom: 10px; }
  .lr .prov { border: 2px solid #b91c1c; color: #b91c1c; text-align: center; font-weight: 700; padding: 6px; margin-bottom: 10px; letter-spacing: .08em; }
  .lr table.info { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
  .lr table.info td { padding: 3px 6px; vertical-align: top; }
  .lr table.info td.k { color: #52606d; width: 16%; white-space: nowrap; }
  .lr table.res { width: 100%; border-collapse: collapse; margin-top: 4px; }
  .lr table.res th { background: #e1f0fa; text-align: left; padding: 6px; border-bottom: 1px solid #9fb3c8; font-size: 11.5px; text-transform: uppercase; letter-spacing: .04em; }
  .lr table.res td { padding: 6px; border-bottom: 1px solid #e4e7eb; }
  .lr .flag { font-weight: 700; }
  .lr .crit { color: #b91c1c; }
  .lr .note { margin-top: 10px; white-space: pre-line; }
  .lr .sign { margin-top: 36px; display: flex; justify-content: space-between; }
  .lr .sign div { width: 45%; border-top: 1px solid #9aa5b1; padding-top: 4px; }
  .lr .foot { margin-top: 18px; color: #52606d; font-size: 11px; white-space: pre-line; border-top: 1px solid #e4e7eb; padding-top: 6px; }
</style>
<div class="lr">
  {% if doc.status != "Reported" %}
  <div class="prov">PROVISIONAL &middot; NOT VERIFIED &middot; {{ doc.status | upper }}</div>
  {% endif %}
  <h2>{{ doc.item_name or doc.item }}</h2>
  <div class="sub">{{ _("Laboratory Report") }}{% if dept %} &middot; {{ dept }}{% endif %}</div>

  <table class="info">
    <tr>
      <td class="k">{{ _("Patient") }}</td><td><b>{{ doc.patient_name or "" }}</b></td>
      <td class="k">{{ _("Report No.") }}</td><td>{{ doc.name }}</td>
    </tr>
    <tr>
      <td class="k">{{ _("UHIN") }}</td><td>{{ visit.uhin_id if visit else "" }}</td>
      <td class="k">{{ _("Sample ID") }}</td><td>{{ doc.lab_sample or "" }}</td>
    </tr>
    <tr>
      <td class="k">{{ _("Age / Sex") }}</td><td>{{ doc.age or "" }}{% if doc.age %} {{ _("yrs") }}{% endif %} / {{ doc.sex or "" }}</td>
      <td class="k">{{ _("Collected On") }}</td><td>{{ doc.get_formatted("sample_collected_on") }}</td>
    </tr>
    <tr>
      <td class="k">{{ _("Referred By") }}</td><td>{{ doctor or "" }}</td>
      <td class="k">{{ _("Reported On") }}</td><td>{{ doc.get_formatted("reported_on") }}</td>
    </tr>
  </table>

  {% if doc.results %}
  <table class="res">
    <thead><tr><th>{{ _("Parameter") }}</th><th>{{ _("Result") }}</th><th>{{ _("Unit") }}</th><th>{{ _("Normal Range") }}</th><th>{{ _("Flag") }}</th></tr></thead>
    <tbody>
      {% for r in doc.results %}
      <tr>
        <td>{{ r.parameter }}</td>
        <td>{% if r.flag %}<b>{{ r.result_value or "" }}</b>{% else %}{{ r.result_value or "" }}{% endif %}</td>
        <td>{{ r.unit or "" }}</td>
        <td>{{ r.normal_range or "" }}</td>
        <td class="flag {% if r.flag and r.flag.startswith('Critical') %}crit{% endif %}">{{ r.flag or "" }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>
  {% endif %}

  {% if doc.result %}<div class="note"><b>{{ _("Result") }}:</b> {{ doc.result }}</div>{% endif %}
  {% if doc.normal_range and not doc.results %}<div class="note"><b>{{ _("Normal Range") }}:</b> {{ doc.normal_range }}</div>{% endif %}
  {% if doc.remarks %}<div class="note"><b>{{ _("Remarks") }}:</b> {{ doc.remarks }}</div>{% endif %}

  <div class="sign">
    <div>{{ _("Entered by") }}: {{ user_name(doc.result_entered_by) if doc.result_entered_by else "" }}</div>
    <div>{{ signature_label or _("Verified by") }}: {{ user_name(doc.verified_by) if doc.verified_by else "" }}</div>
  </div>
  {% if report_footer %}<div class="foot">{{ report_footer }}</div>{% endif %}
</div>
